// seed: tests/seed.spec.ts (гость) · прод, только чтение. Случай הון עצמי = 0 — в loan-edge-cases.spec.ts.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, resultValue, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`ROE «—» при отрицательном הון עצמי (кредит 700,000 > инвестиции 600,000) #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, { ...SET1, loanAmount: '700000' });

      await expectResult(page, 'הון עצמי נדרש', '-100,000 ₪');
      await expectResult(page, 'תשואה שנתית על ההון העצמי', '—');
      const roe = await resultValue(page, 'תשואה שנתית על ההון העצמי');
      expect(roe, 'ROE без Infinity/NaN/%').not.toMatch(/Infinity|NaN|%/);
    });
  }
});
